from griffe.extensions import Extension
from griffe import load

class CheckedExtension(Extension):
    """Extension that appends ' [checked]' to all function docstrings."""

    def load(self, griffe):
        """Modify docstrings of all functions in the loaded object."""
        self._process_docstrings(griffe)

    def _process_docstrings(self, obj):
        """Recursively process and modify function docstrings."""
        # Append [checked] to function docstrings
        if obj.is_function and obj.docstring:
            obj.docstring.value += " [checked]"

        # Recursively process members
        if hasattr(obj, 'members'):
            for member in obj.members.values():
                self._process_docstrings(member)

# Load package with extension aggregated in the list
extension = CheckedExtension()
package = load("mypkg", extensions=[extension])
